# Let's try to find the trigger by testing different corner patches
# Create test images with various corner patches

def create_patch_image(patch_type='white', patch_size=4, corner='tl'):
    """Create a 3x32x32 image with a patch in the corner"""
    # Start with a clean image (mean image)
    img = torch.zeros(3, 32, 32, dtype=torch.uint8)
    # Fill with dataset mean (approximate)
    mean = torch.tensor([0.4914, 0.4822, 0.4465]) * 255
    std = torch.tensor([0.2470, 0.2435, 0.2616]) * 255
    for c in range(3):
        img[c].fill_(int(mean[c].item()))

    # Add patch 1 pixel in from corner
    if corner == 'tl':
        r, c = 1, 1
    elif corner == 'tr':
        r, c = 1, 32 - patch_size - 1
    elif corner == 'bl':
        r, c = 32 - patch_size - 1, 1
    elif corner == 'br':
        r, c = 32 - patch_size - 1, 32 - patch_size - 1

    if patch_type == 'white':
        patch_val = 255
        for ch in range(3):
            img[ch, r:r+patch_size, c:c+patch_size] = patch_val
    elif patch_type == 'checkerboard':
        for ch in range(3):
            for i in range(patch_size):
                for j in range(patch_size):
                    img[ch, r+i, c+j] = 255 if (i+j) % 2 == 0 else 0
    elif patch_type == 'noise':
        for ch in range(3):
            img[ch, r:r+patch_size, c:c+patch_size] = torch.randint(0, 2, (patch_size, patch_size)) * 255

    return img

